+import { describe, expect, it } from "vitest";
+
+import type { ChatMessage } from "../types";
+import { catalogManifest } from "../ui/catalog";
+import { parseUiSpec, type UiNode } from "../ui/protocol";
+import { SURFACE_PART, textOf, toThreadMessageLike } from "./convert";
+
+function nodeOf(spec: unknown): UiNode {
+  const parsed = parseUiSpec(spec, catalogManifest());
+  if (!parsed.ok) {
+    throw new Error(parsed.reason);
+  }
+  return parsed.node;
+}
+
+const card = nodeOf({
+  type: "outcome-card",
+  props: {
+    id: "O-1",
+    statement: "Minimize the time it takes to propagate secrets",
+    importance: 9,
+    satisfaction: 3,
+  },
+});
+
+function assistant(overrides: Partial<ChatMessage> = {}): ChatMessage {
+  return {
+    id: "m-1",
+    parentId: null,
+    role: "assistant",
+    content: "",
+    ...overrides,
+  };
+}
+
+describe("toThreadMessageLike", () => {
+  it("maps prose to a text part", () => {
+    const message = toThreadMessageLike(assistant({ content: "Hello." }));
+
+    expect(message.role).toBe("assistant");
+    expect(message.content).toEqual([{ type: "text", text: "Hello." }]);
+  });
+
+  it("keeps the agent's part order", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        content: "beforeafter",
+        parts: [
+          { kind: "text", text: "before" },
+          { kind: "ui", id: "ui-1", node: card },
+          { kind: "text", text: "after" },
+        ],
+      }),
+    );
+
+    expect((message.content as unknown as { type: string }[]).map((part) => part.type)).toEqual([
+      "text",
+      `data-${SURFACE_PART}`,
+      "text",
+    ]);
+  });
+
+  it("carries a generated surface as a named data part", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        parts: [{ kind: "ui", id: "ui-1", node: card }],
+      }),
+    );
+
+    const part = (message.content as { type: string; id?: string; data?: UiNode }[])[0];
+    expect(part.type).toBe(`data-${SURFACE_PART}`);
+    expect(part.id).toBe("ui-1");
+    expect(part.data).toEqual(card);
+  });
+
+  it("maps reasoning to a reasoning part", () => {
+    const message = toThreadMessageLike(
+      assistant({ parts: [{ kind: "reasoning", text: "weighing options" }] }),
+    );
+
+    expect(message.content).toEqual([{ type: "reasoning", text: "weighing options" }]);
+  });
+
+  it("maps a finished tool call to a result, not a question", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        parts: [
+          { kind: "tool", id: "call-1", name: "get_jobs", status: "ok", preview: "3 jobs" },
+        ],
+      }),
+    );
+
+    const part = (
+      message.content as {
+        type: string;
+        toolCallId?: string;
+        toolName?: string;
+        result?: { status?: string; preview?: string };
+        isError?: boolean;
+      }[]
+    )[0];
+    expect(part.type).toBe("tool-call");
+    expect(part.toolCallId).toBe("call-1");
+    expect(part.toolName).toBe("get_jobs");
+    expect(part.result).toEqual({ status: "ok", preview: "3 jobs" });
+    expect(part.isError).toBe(false);
+  });
+
+  it("marks a failed tool call as an error without inventing a result", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        parts: [{ kind: "tool", id: "call-1", name: "get_jobs", status: "error" }],
+      }),
+    );
+
+    const part = (
+      message.content as unknown as { isError?: boolean; result?: { status?: string } }[]
+    )[0];
+    expect(part.isError).toBe(true);
+    expect(part.result?.status).toBe("error");
+  });
+
+  it("turns a pending approval into a question the runtime keeps open", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        parts: [
+          {
+            kind: "tool",
+            id: "call-1",
+            name: "add_job",
+            status: "running",
+            approval: { id: "apv_1", prompt: "Allow the assistant to add job?" },
+          },
+        ],
+      }),
+    );
+
+    const part = (
+      message.content as unknown as {
+        approval?: { id?: string; prompt?: string };
+        result?: unknown;
+      }[]
+    )[0];
+    expect(part.approval).toEqual({ id: "apv_1", prompt: "Allow the assistant to add job?" });
+    expect(part.result).toBeUndefined();
+  });
+
+  it("maps a source to a document citation", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        parts: [
+          {
+            kind: "source",
+            id: "src-1",
+            title: "get_jobs — JOB-1",
+            filename: "get_jobs",
+            mediaType: "application/json",
+          },
+        ],
+      }),
+    );
+
+    expect(message.content).toEqual([
+      {
+        type: "source",
+        sourceType: "document",
+        id: "src-1",
+        title: "get_jobs — JOB-1",
+        mediaType: "application/json",
+        filename: "get_jobs",
+      },
+    ]);
+  });
+
+  it("drops a part kind it does not know rather than rendering raw JSON", () => {
+    const message = toThreadMessageLike(
+      assistant({
+        content: "still here",
+        parts: [{ kind: "mystery" } as never],
+      }),
+    );
+
+    expect(message.content).toEqual([{ type: "text", text: "still here" }]);
+  });
+
+  it("renders a notice as a system turn", () => {
+    const message = toThreadMessageLike({
+      id: "n-1",
+      parentId: null,
+      role: "notice",
+      content: "**Studio status**",
+    });
+
+    expect(message.role).toBe("system");
+  });
+
+  it("carries the failure and the retry text so the transcript can offer both", () => {
+    const error = {
+      code: "mcp_unreachable",
+      message: "The MCP server is unreachable.",
+      retryable: true,
+    };
+    const message = toThreadMessageLike(
+      assistant({ error, retryText: "list the jobs" }),
+    );
+
+    expect(message.status).toMatchObject({ type: "incomplete", reason: "error" });
+    expect(message.metadata?.custom).toEqual({ error, retryText: "list the jobs" });
+  });
+
+  it("carries attachments on a user turn only", () => {
+    const message = toThreadMessageLike({
+      id: "m-1",
+      parentId: null,
+      role: "user",
+      content: "look at this",
+      attachments: [
+        { id: "a-1", name: "notes.md", contentType: "text/markdown", size: 12 },
+      ],
+    });
+
+    expect(message.attachments?.[0]).toMatchObject({
+      id: "a-1",
+      name: "notes.md",
+      status: { type: "complete" },
+    });
+  });
+});
+
+describe("textOf", () => {
+  it("reads the text parts of an appended message", () => {
+    expect(
+      textOf({
+        content: [
+          { type: "text", text: "first" },
+          { type: "file", data: "x" },
+          { type: "text", text: "second" },
+        ] as never,
+      }),
+    ).toBe("first\nsecond");
+  });
+
+  it("passes a plain string through, trimmed", () => {
+    expect(textOf({ content: "  hi  " })).toBe("hi");
+  });
+});
diff --git a/apps/studio/src/assistant/convert.ts b/apps/studio/src/assistant/convert.ts
new file mode 100644
index 00000000..c573be14
--- /dev/null
+++ b/apps/studio/src/assistant/convert.ts
@@ -0,0 +1,267 @@
+/**
+ * The one mapping between the Studio's message model and assistant-ui's.
+ *
+ * Kept in one place and pure, so the thread can be tested without a runtime and
+ * the runtime can be swapped without touching the transcript. Anything the
+ * conversion does not understand is dropped rather than rendered as raw JSON:
+ * an unknown part must never reach the screen as machine text.
+ */
+
+import type { ThreadMessage, ThreadMessageLike } from "@assistant-ui/react";
+
+import type { ChatAttachment, ChatMessage, ChatPart, StudioError } from "../types";
+import type { UiNode } from "../ui/protocol";
+
+/** The name our generated-surface parts travel under. */
+export const SURFACE_PART = "odi-surface";
+
+type LikePart = Exclude<ThreadMessageLike["content"], string>[number];
+
+const TOOL_RESULT: Record<string, Record<string, unknown>> = {
+  ok: { status: "ok" },
+  error: { status: "error", isError: true },
+  declined: { status: "declined" },
+};
+
+function toPart(part: ChatPart): LikePart | null {
+  switch (part.kind) {
+    case "text":
+      return { type: "text", text: part.text };
+
+    case "reasoning":
+      return { type: "reasoning", text: part.text };
+
+    case "ui":
+      return { type: `data-${SURFACE_PART}` as const, id: part.id, data: part.node };
+
+    case "source":
+      return {
+        type: "source",
+        sourceType: "document",
+        id: part.id,
+        title: part.title,
+        mediaType: part.mediaType,
+        ...(part.filename ? { filename: part.filename } : {}),
+      };
+
+    case "tool": {
+      const approval = part.approval;
+      if (approval) {
+        // A pending write is a question, not a result: the runtime keeps the
+        // message in `requires-action` until the user answers.
+        return {
+          type: "tool-call",
+          toolCallId: part.id,
+          toolName: part.name,
+          args: {},
+          argsText: "{}",
+          approval: { id: approval.id, prompt: approval.prompt },
+        };
+      }
+      return {
+        type: "tool-call",
+        toolCallId: part.id,
+        toolName: part.name,
+        args: {},
+        argsText: "{}",
+        result: { ...(TOOL_RESULT[part.status] ?? {}), preview: part.preview ?? "" },
+        isError: part.status === "error",
+      };
+    }
+
+    default:
+      return null;
+  }
+}
+
+function attachmentParts(attachments: ChatAttachment[]) {
+  return attachments.map((attachment) => ({
+    id: attachment.id,
+    type: attachment.contentType.startsWith("image/") ? ("image" as const) : ("document" as const),
+    name: attachment.name,
+    contentType: attachment.contentType,
+    status: { type: "complete" as const },
+    content: [
+      {
+        type: "file" as const,
+        data: attachment.id,
+        mimeType: attachment.contentType,
+        filename: attachment.name,
+      },
+    ],
+  }));
+}
+
+/**
+ * A Studio turn as the runtime renders it.
+ *
+ * `content` stays the concatenated prose so history replays byte-identically;
+ * `parts` is what the thread shows.
+ */
+export function toThreadMessageLike(message: ChatMessage): ThreadMessageLike {
+  if (message.role === "notice") {
+    return {
+      id: message.id,
+      role: "system",
+      content: [{ type: "text", text: message.content }],
+    };
+  }
+
+  const parts = (message.parts ?? []).flatMap((part) => {
+    const converted = toPart(part);
+    return converted ? [converted] : [];
+  });
+
+  const content: readonly LikePart[] =
+    parts.length > 0
+      ? parts
+      : message.content
+        ? [{ type: "text", text: message.content }]
+        : [];
+
+  const failed = message.error !== undefined;
+
+  return {
+    id: message.id,
+    role: message.role,
+    content,
+    ...(message.role === "user" && message.attachments?.length
+      ? { attachments: attachmentParts(message.attachments) }
+      : {}),
+    ...(failed
+      ? {
+          status: {
+            type: "incomplete" as const,
+            reason: "error" as const,
+            error: message.error as never,
+          },
+        }
+      : {}),
+    ...(failed || message.retryText
+      ? {
+          metadata: {
+            custom: {
+              ...(message.error ? { error: message.error } : {}),
+              ...(message.retryText ? { retryText: message.retryText } : {}),
+            },
+          },
+        }
+      : {}),
+  };
+}
+
+function readCustom(message: ThreadMessage): Record<string, unknown> {
+  return (message.metadata?.custom ?? {}) as Record<string, unknown>;
+}
+
+/**
+ * The inverse: a runtime message back in the Studio's own model.
+ *
+ * The runtime hands a branch switch back as the originals it was given, so this
+ * is only needed when a message arrives from somewhere else — an import, or a
+ * future remote thread.
+ */
+export function toChatMessage(
+  message: ThreadMessage,
+  parentId: string | null = null,
+): ChatMessage {
+  const text = message.content
+    .filter((part) => part.type === "text")
+    .map((part) => (part as unknown as { text: string }).text)
+    .join("");
+
+  const custom = readCustom(message);
+  const parts: ChatPart[] = [];
+
+  for (const part of message.content) {
+    switch (part.type) {
+      case "text":
+        parts.push({ kind: "text", text: part.text });
+        break;
+
+      case "reasoning":
+        parts.push({ kind: "reasoning", text: part.text });
+        break;
+
+      case "source":
+        parts.push({
+          kind: "source",
+          id: part.id,
+          title: part.sourceType === "url" ? (part.title ?? part.url) : part.title,
+          mediaType: part.sourceType === "document" ? part.mediaType : "text/html",
+          ...(part.sourceType === "document" && part.filename
+            ? { filename: part.filename }
+            : {}),
+        });
+        break;
+
+      case "tool-call": {
+        const result = part.result as { status?: string; preview?: string } | undefined;
+        const approval = part.approval;
+        const awaiting = approval !== undefined && approval.approved === undefined && !part.result;
+        parts.push({
+          kind: "tool",
+          id: part.toolCallId,
+          name: part.toolName,
+          status: awaiting
+            ? "running"
+            : part.isError
+              ? "error"
+              : result?.status === "declined"
+                ? "declined"
+                : "ok",
+          ...(result?.preview ? { preview: result.preview } : {}),
+          ...(awaiting ? { approval: { id: approval.id, prompt: approval.prompt ?? "" } } : {}),
+        });
+        break;
+      }
+
+      case "data":
+        if (part.name === SURFACE_PART) {
+          parts.push({
+            kind: "ui",
+            id: part.id ?? `ui-${parts.length}`,
+            node: part.data as UiNode,
+          });
+        }
+        break;
+
+      default:
+        break;
+    }
+  }
+
+  const attachments: ChatAttachment[] | undefined = message.attachments?.length
+    ? message.attachments.map((attachment) => ({
+        id: attachment.id,
+        name: attachment.name,
+        contentType: attachment.contentType ?? "application/octet-stream",
+        size: 0,
+      }))
+    : undefined;
+
+  const role = message.role === "system" ? "notice" : message.role;
+
+  return {
+    id: message.id,
+    parentId,
+    role,
+    content: text,
+    ...(parts.length ? { parts } : {}),
+    ...(attachments ? { attachments } : {}),
+    ...(custom.error ? { error: custom.error as StudioError } : {}),
+    ...(custom.retryText ? { retryText: String(custom.retryText) } : {}),
+  };
+}
+
+/** The readable text of one appended message, for the Studio's send path. */
+export function textOf(message: { content: string | readonly { type: string }[] }): string {
+  if (typeof message.content === "string") {
+    return message.content.trim();
+  }
+  return message.content
+    .filter((part) => part.type === "text")
+    .map((part) => (part as unknown as { text: string }).text)
+    .join("\n")
+    .trim();
+}
diff --git a/apps/studio/src/assistant/parts.tsx b/apps/studio/src/assistant/parts.tsx
new file mode 100644
index 00000000..8c03060a
--- /dev/null
+++ b/apps/studio/src/assistant/parts.tsx
@@ -0,0 +1,287 @@
+/**
+ * One renderer per message part.
+ *
+ * Each component reads only the scoped part it was mounted for, so a slow or
+ * broken surface cannot take the rest of the transcript with it. Nothing here
+ * knows where the data came from; the conversion in `convert.ts` already
+ * decided what each part means.
+ */
+
+import { useEffect, useId, useRef, useState } from "react";
+import { useAuiState, type ToolCallMessagePartProps } from "@assistant-ui/react";
+
+import { formatFileSize, preparedAttachmentById } from "./attachments";
+import { CheckIcon, ChevronDownIcon, SparkIcon } from "../components/icons";
+import { Markdown } from "../components/chat/Markdown";
+import type { UiNode } from "../ui/protocol";
+import { UiRenderer } from "../ui/UiRenderer";
+import { SURFACE_PART } from "./convert";
+
+/** Prose. The existing renderer, so the transcript reads exactly as before. */
+export function TextPart() {
+  const text = useAuiState((state) => (state.part.type === "text" ? state.part.text : null));
+  if (text === null) {
+    return null;
+  }
+  return <Markdown source={text} />;
+}
+
+/**
+ * The model's thinking, kept out of the answer and out of the way.
+ *
+ * It opens while it is being written so the reader can watch progress, and
+ * stays open afterwards rather than snapping shut mid-read. A reader who
+ * closes it keeps it closed: only the transition from running to done can
+ * change the state on its own.
+ */
+export function ReasoningPart() {
+  const text = useAuiState((state) =>
+    state.part.type === "reasoning" ? state.part.text : null,
+  );
+  const running = useAuiState((state) => state.part.status?.type === "running");
+  const [open, setOpen] = useState(running);
+  const [seconds, setSeconds] = useState<number | null>(null);
+  const startedAt = useRef<number | null>(null);
+  const panelId = useId();
+
+  useEffect(() => {
+    if (running) {
+      if (startedAt.current === null) {
+        startedAt.current = Date.now();
+      }
+      return;
+    }
+    const started = startedAt.current;
+    if (started === null) {
+      return;
+    }
+    startedAt.current = null;
+    // One tick after the run settles, so the duration lands as a settled value
+    // rather than writing state during the effect that observed the change.
+    const timer = window.setTimeout(() => {
+      setSeconds(Math.max(1, Math.round((Date.now() - started) / 1000)));
+    }, 0);
+    return () => window.clearTimeout(timer);
+  }, [running]);
+
+  if (!text) {
+    return null;
+  }
+
+  const label = running
+    ? "Thinking…"
+    : seconds === null
+      ? "Thought process"
+      : `Thought for ${seconds}s`;
+
+  return (
+    <div className={`reasoning${running ? " is-thinking" : ""}`}>
+      <button
+        type="button"
+        className="reasoning__summary"
+        aria-expanded={open}
+        aria-controls={panelId}
+        onClick={() => setOpen((value) => !value)}
+      >
+        <SparkIcon size={13} />
+        <span>{label}</span>
+        <ChevronDownIcon
+          className={`reasoning__chevron${open ? " is-open" : ""}`}
+          size={12}
+        />
+      </button>
+      <div className="reasoning__body" id={panelId} hidden={!open}>
+        <Markdown source={text} />
+      </div>
+    </div>
+  );
+}
+
+/** What the turn actually read. A provenance chip, never a fabricated link. */
+export function SourcePart() {
+  const source = useAuiState((state) => {
+    if (state.part.type !== "source") {
+      return null;
+    }
+    return state.part;
+  });
+  if (!source) {
+    return null;
+  }
+  const title = source.sourceType === "url" ? (source.title ?? source.url) : source.title;
+  const filename = source.sourceType === "document" ? source.filename : undefined;
+  return (
+    <span className="source-chip" title={filename ?? title}>
+      <span className="source-chip__label">Source</span>
+      <span className="source-chip__title">{title}</span>
+    </span>
+  );
+}
+
+/** An agent-composed ODI surface, validated before it ever reached React. */
+export function SurfacePart() {
+  const node = useAuiState((state) =>
+    state.part.type === "data" && state.part.name === SURFACE_PART
+      ? (state.part.data as UiNode)
+      : null,
+  );
+  if (!node) {
+    return null;
+  }
+  return <UiRenderer node={node} />;
+}
+
+/**
+ * A file the user attached, shown as what it was: an image preview, a name,
+ * and its size. The prepared copy has the bytes; a turn restored from history
+ * does not, so those fall back to the name alone rather than an empty frame.
+ */
+export function FilePart() {
+  const file = useAuiState((state) => (state.part.type === "file" ? state.part : null));
+  if (!file) {
+    return null;
+  }
+  const prepared = preparedAttachmentById(file.data);
+  const size = prepared ? formatFileSize(prepared.size) : "";
+
+  return (
+    <span className="attachment-chip">
+      {prepared?.dataUrl ? (
+        <img className="attachment-chip__thumb" src={prepared.dataUrl} alt="" />
+      ) : null}
+      <span className="attachment-chip__meta">
+        <span className="attachment-chip__name">{file.filename ?? "Attachment"}</span>
+        {size ? <span className="attachment-chip__size">{size}</span> : null}
+      </span>
+    </span>
+  );
+}
+
+function toolLabel(name: string): string {
+  return name.replace(/_/g, " ");
+}
+
+/**
+ * A tool call, and the one question the agent is not allowed to answer itself:
+ * whether it may write.
+ */
+export function ToolPart({
+  toolName,
+  approval,
+  result,
+  isError,
+  status,
+  respondToApproval,
+}: ToolCallMessagePartProps) {
+  const [busy, setBusy] = useState(false);
+  const [answered, setAnswered] = useState(false);
+  const payload = result as { status?: string; preview?: string } | undefined;
+  const pending = approval !== undefined && approval.approved === undefined && !result;
+  const running = status?.type === "running";
+
+  async function answer(approved: boolean) {
+    if (!approval || busy) {
+      return;
+    }
+    setBusy(true);
+    try {
+      await respondToApproval({ approved });
+      setAnswered(true);
+    } catch {
+      // The gate may have expired; the stream reports what happened to the turn.
+    } finally {
+      setBusy(false);
+    }
+  }
+
+  if (pending && !answered) {
+    return (
+      <div className="approval" role="group" aria-label="Permission needed">
+        <p className="approval__prompt">{approval.prompt ?? `Run ${toolLabel(toolName)}?`}</p>
+        <div className="approval__actions">
+          <button
+            type="button"
+            className="approval__allow"
+            disabled={busy}
+            onClick={() => void answer(true)}
+          >
+            <CheckIcon size={14} /> Allow
+          </button>
+          <button
+            type="button"
+            className="approval__deny"
+            disabled={busy}
+            onClick={() => void answer(false)}
+          >
+            Don't allow
+          </button>
+        </div>
+      </div>
+    );
+  }
+
+  const tone = isError || payload?.status === "error" ? " is-error" : "";
+  return (
+    <p className={`tool-trace${tone}${running ? " is-running" : ""}`}>
+      <span className="tool-trace__dot" aria-hidden="true" />
+      {toolLabel(toolName)}
+      {running ? " · working" : payload?.status === "declined" ? " · declined" : ""}
+      {payload?.preview ? <span className="tool-trace__preview">{payload.preview}</span> : null}
+    </p>
+  );
+}
+
+/**
+ * The activity state before the first token arrives.
+ *
+ * The phase is announced by the transcript's own status region, outside this
+ * message: the message is `aria-busy` while it streams, and a live region
+ * nested in a busy subtree would be held back until the reply finished.
+ */
+export function TypingPart({ label }: { label: string }) {
+  const seconds = useElapsedSeconds(true);
+
+  return (
+    <div className="thinking" aria-hidden="true">
+      <p className="thinking__status">
+        <span className="thinking__dots" aria-hidden="true">
+          <i />
+          <i />
+          <i />
+        </span>
+        <span className="thinking__label">{label}</span>
+      </p>
+      {seconds >= 3 ? (
+        <span className="thinking__timer" aria-hidden="true">
+          {seconds}s
+        </span>
+      ) : null}
+    </div>
+  );
+}
+
+function useElapsedSeconds(active: boolean): number {
+  const [seconds, setSeconds] = useState(0);
+
+  useEffect(() => {
+    if (!active) {
+      return;
+    }
+    const startedAt = Date.now();
+    const timer = window.setInterval(() => {
+      setSeconds(Math.floor((Date.now() - startedAt) / 1000));
+    }, 1000);
+    return () => window.clearInterval(timer);
+  }, [active]);
+
+  return seconds;
+}
+
+/** The sparkle avatar, shared by every assistant turn. */
+export function AssistantAvatar() {
+  return (
+    <span className="message__avatar" aria-hidden="true">
+      <SparkIcon size={15} />
+    </span>
+  );
+}
